public class JDecInc1 {
	public static void main(String[] args) {
		//Khatwa 1: Ta'rif al-mutaghayyirat
		int a = 4; 
		int b = 5;
		//Khatwa 2: Tanfeedh al-amaliyyat wa tabaa al-nateeja al-oola
		System.out.println( a++ - b-- ); 
		//Khatwa 3: Tanfeedh al-amaliyyat wa tabaa al-nateeja al-thanya
		System.out.println( ++a - --b ); 
	}
}
